-- Family Homecare / FOMAG: las actas generales van DENTRO de los F-FAM-11 (2026-10-29)
-- Del Excel "ACTA DE ENTREGA DE EQUIPOS FAMILY" y "ACTA DE ENTREGA INSUMO (MASCARA)":
--   · Entrega CPAP - BPAP (F-FAM-11)    → + hoja "Acta de entrega de equipos" + hoja "Entrega de insumo (máscara)"
--   · Entrega Oxígeno (F-FAM-11)        → + hoja "Acta de entrega de equipos"
--   · Entrega Otros equipos (F-FAM-11)  → + hoja "Acta de entrega de equipos"
-- Agrega las hojas al FINAL de cada plantilla (no reemplaza lo que ya tiene, así se
-- conservan los cambios hechos en Configuración). Si ya las tiene, no hace nada.
-- Generado desde src/lib/actas/plantillas-base.js (hojaEntregaFamily, hojaMascaraFamily).
-- Las actas ya firmadas no cambian: cada una guarda su copia de los bloques.

-- 0) Respaldo (borrarlo cuando se confirme el resultado; ver el final)
CREATE TABLE IF NOT EXISTS respaldo_plantillas_f11_20261029 AS
SELECT id, nombre, bloques FROM plantillas_acta
WHERE nombre IN ('Family Homecare / FOMAG — Entrega CPAP - BPAP (F-FAM-11)', 'Family Homecare / FOMAG — Entrega Oxígeno (F-FAM-11)', 'Family Homecare / FOMAG — Entrega Otros equipos (F-FAM-11)');
-- Con RLS y sin políticas: nadie la lee desde la app mientras exista
ALTER TABLE respaldo_plantillas_f11_20261029 ENABLE ROW LEVEL SECURITY;

BEGIN;

UPDATE plantillas_acta SET bloques = bloques || $hojas$[{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":58}],"ancho_logo":24,"centro":[{"texto":"ACTA GENERAL DE EQUIPOS MEDICOS DOMICILIARIOS O SUMINISTRO OXIGENO DOMICILIARIO","estilo":"titulo"}]},{"tipo":"campos","titulo":"ENTREGA DE EQUIPOS","columnas":3,"borde":true,"campos":[{"etiqueta":"CIUDAD","valor":"{{ciudad}}"},{"etiqueta":"FECHA","valor":"{{fecha}}"},{"etiqueta":"HORA","valor":"{{hora}}"},{"etiqueta":"EQUIPO ENTREGADO:","valor":"{{equipo_descripcion}}"},{"etiqueta":"MARCA:","valor":"{{equipo_marca}}"},{"etiqueta":"MODELO:","valor":"{{equipo_modelo}}"},{"etiqueta":"SERIAL","valor":"{{equipo_serie}}"},{"etiqueta":"ACCESORIOS:","valor":"{{insumos_resumen}}","span":2},{"etiqueta":"OTROS EQUIPOS ENTREGADOS:","valor":"{{otros_equipos}}","span":3},{"etiqueta":"QUIEN ENTREGA:","valor":"{{entrega_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"entrega"},{"etiqueta":"QUIEN RECIBE:","valor":"{{recibe_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"recibe"},{"etiqueta":"DIRECCION:","valor":"{{paciente_direccion}}","span":2},{"etiqueta":"TELEFONO","valor":"{{recibe_telefono}}"},{"etiqueta":"NOMBRE DEL PACIENTE:","valor":"{{paciente_nombre}}","span":3},{"etiqueta":"OBSERVACIONES: ( Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la entrega)","valor":"{{observaciones}}","span":3,"arriba":true}]},{"tipo":"texto","tamano":11,"texto":"Por medio de la presente acta se hace constar la entrega, devolucion, recarga y tenencia actual de los equipos biomedicos y/o suministros de oxigeno domiciliario en calidad de prestamo . La custodia y buen uso de los equipos entregados antes descritos son responsalidad del paciente o familiar, a partir de la fecha de entrega asumen el compromiso de su cuidado."},{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":58}],"ancho_logo":24,"centro":[{"texto":"ACTA GENERAL DE EQUIPOS MEDICOS DOMICILIARIOS O SUMINISTRO OXIGENO DOMICILIARIO","estilo":"titulo"}]},{"tipo":"campos","titulo":"ENTREGA DE INSUMO","columnas":3,"borde":true,"campos":[{"etiqueta":"CIUDAD","valor":"{{ciudad}}"},{"etiqueta":"FECHA","valor":"{{fecha}}"},{"etiqueta":"HORA","valor":"{{hora}}"},{"etiqueta":"INSUMO ENTREGADO:","valor":"{{mascara_descripcion}}"},{"etiqueta":"MARCA:","valor":"{{mascara_marca}}"},{"etiqueta":"MODELO:","valor":"{{mascara_modelo}}"},{"etiqueta":"REG. INVIMA","valor":"{{mascara_invima}}","span":3},{"etiqueta":"OTROS EQUIPOS ENTREGADOS:","valor":"{{equipos_resumen}}","span":3},{"etiqueta":"QUIEN ENTREGA:","valor":"{{entrega_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"entrega"},{"etiqueta":"QUIEN RECIBE:","valor":"{{recibe_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"recibe"},{"etiqueta":"DIRECCION:","valor":"{{paciente_direccion}}","span":2},{"etiqueta":"TELEFONO","valor":"{{recibe_telefono}}"},{"etiqueta":"NOMBRE DEL PACIENTE:","valor":"{{paciente_nombre}}","span":3},{"etiqueta":"OBSERVACIONES: ( Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la entrega)","valor":"{{observaciones}}","span":3,"arriba":true}]},{"tipo":"texto","tamano":11,"texto":"Por medio de la presente acta se hace constar la entrega, devolucion, recarga y tenencia actual de los equipos biomedicos y/o suministros de oxigeno domiciliario en calidad de prestamo . La custodia y buen uso de los equipos entregados antes descritos son responsalidad del paciente o familiar, a partir de la fecha de entrega asumen el compromiso de su cuidado."}]$hojas$::jsonb
WHERE nombre = 'Family Homecare / FOMAG — Entrega CPAP - BPAP (F-FAM-11)' AND NOT bloques @> '[{"tipo":"campos","titulo":"ENTREGA DE EQUIPOS"}]'::jsonb;

UPDATE plantillas_acta SET bloques = bloques || $hojas$[{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":58}],"ancho_logo":24,"centro":[{"texto":"ACTA GENERAL DE EQUIPOS MEDICOS DOMICILIARIOS O SUMINISTRO OXIGENO DOMICILIARIO","estilo":"titulo"}]},{"tipo":"campos","titulo":"ENTREGA DE EQUIPOS","columnas":3,"borde":true,"campos":[{"etiqueta":"CIUDAD","valor":"{{ciudad}}"},{"etiqueta":"FECHA","valor":"{{fecha}}"},{"etiqueta":"HORA","valor":"{{hora}}"},{"etiqueta":"EQUIPO ENTREGADO:","valor":"{{equipo_descripcion}}"},{"etiqueta":"MARCA:","valor":"{{equipo_marca}}"},{"etiqueta":"MODELO:","valor":"{{equipo_modelo}}"},{"etiqueta":"SERIAL","valor":"{{equipo_serie}}"},{"etiqueta":"ACCESORIOS:","valor":"{{insumos_resumen}}","span":2},{"etiqueta":"OTROS EQUIPOS ENTREGADOS:","valor":"{{otros_equipos}}","span":3},{"etiqueta":"QUIEN ENTREGA:","valor":"{{entrega_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"entrega"},{"etiqueta":"QUIEN RECIBE:","valor":"{{recibe_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"recibe"},{"etiqueta":"DIRECCION:","valor":"{{paciente_direccion}}","span":2},{"etiqueta":"TELEFONO","valor":"{{recibe_telefono}}"},{"etiqueta":"NOMBRE DEL PACIENTE:","valor":"{{paciente_nombre}}","span":3},{"etiqueta":"OBSERVACIONES: ( Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la entrega)","valor":"{{observaciones}}","span":3,"arriba":true}]},{"tipo":"texto","tamano":11,"texto":"Por medio de la presente acta se hace constar la entrega, devolucion, recarga y tenencia actual de los equipos biomedicos y/o suministros de oxigeno domiciliario en calidad de prestamo . La custodia y buen uso de los equipos entregados antes descritos son responsalidad del paciente o familiar, a partir de la fecha de entrega asumen el compromiso de su cuidado."}]$hojas$::jsonb
WHERE nombre IN ('Family Homecare / FOMAG — Entrega Oxígeno (F-FAM-11)', 'Family Homecare / FOMAG — Entrega Otros equipos (F-FAM-11)') AND NOT bloques @> '[{"tipo":"campos","titulo":"ENTREGA DE EQUIPOS"}]'::jsonb;

COMMIT;

-- Verificación: CPAP con 3 hojas, Oxígeno y Otros con 2
SELECT nombre,
  1 + jsonb_array_length(jsonb_path_query_array(bloques, '$[*] ? (@.tipo == "salto_pagina")')) AS hojas,
  bloques @> '[{"tipo":"campos","titulo":"ENTREGA DE INSUMO"}]'::jsonb AS con_mascara
FROM plantillas_acta
WHERE nombre IN ('Family Homecare / FOMAG — Entrega CPAP - BPAP (F-FAM-11)', 'Family Homecare / FOMAG — Entrega Oxígeno (F-FAM-11)', 'Family Homecare / FOMAG — Entrega Otros equipos (F-FAM-11)')
ORDER BY nombre;

